import numpy as np
from scipy.optimize import minimize

def check_n_large(n):
    m = n * (n - 1) // 2
    target = np.arange(1, m + 1)

    def objective(a):
        sums = []
        for i in range(n):
            for j in range(i + 1, n):
                sums.append(a[i] + a[j])
        sums.sort()
        return np.sum((np.array(sums) - target)**2)

