import numpy as np
from scipy.optimize import minimize

def check_n_large(n):
    m = n * (n - 1) // 2
    target = np.arange(1, m + 1)

    def objective(a):
        sums = []
        for i in range(n):
            for j in range(i + 1, n):
                sums.append(a[i] + a[j])
        sums.sort()
        return np.sum((np.array(sums) - target)**2)

    best_fun = float('inf')
    best_a = None
    for _ in range(100):
        a0 = np.random.uniform(0, m/n, n)
        res = minimize(objective, a0, method='Nelder-Mead')
        if res.fun < best_fun:
            best_fun = res.fun
            best_a = res.x

    return best_fun < 1e-6, best_a

for n in [5, 6]:
    possible, a = check_n_large(n)
    print(f"n={n}: {possible}, {a}")
